import React from "react";
import "../s";

const Home = () => {
    return (
        <div className="main-container">

            <h1 className="typewriter">
                Two Types of AI… Which One Would You Trust?
            </h1>

            <p className="description">
                Imagine talking to an AI. Would you prefer one that remembers
                everything forever 😬 or one that smartly forgets sensitive data 🔐?
            </p>

            <button className="explore-btn">
                Let's Explore
            </button>

        </div>
    );
};

export default Home;
